+    }
+
+    private void configureFileNameStrategy(Properties properties) {
+        if (constructorStrategy != null) {
+            if (hasPropertyIncludingDefaults(properties, FILE_NAMES_PROPERTY_NAME)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            ruleViolationFileNameStrategy = constructorStrategy;
+            builtInRandomNames = false;
+            return;
+        }
+
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, RANDOM_FILE_NAMES);
+        if (RANDOM_FILE_NAMES.equals(configured)) {
+            ruleViolationFileNameStrategy = ignored -> UUID.randomUUID().toString();
+            builtInRandomNames = true;
+        } else if (DESCRIPTION_FILE_NAMES.equals(configured)) {
+            ruleViolationFileNameStrategy = TextFileBasedViolationStore::descriptionFileName;
+            builtInRandomNames = false;
+        } else {
+            ruleViolationFileNameStrategy = instantiateStrategy(configured);
+            builtInRandomNames = false;
+        }
+    }
+
+    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
+        try {
+            Class<?> strategyType = Class.forName(className);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)) {
+                throw new IllegalArgumentException("not a RuleViolationFileNameStrategy");
+            }
+            Constructor<?> constructor = strategyType.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s=%s; expected a RuleViolationFileNameStrategy with a public no-argument constructor",
+                    FILE_NAMES_PROPERTY_NAME, className), e);
+        }
+    }
+
+    private void initializeFiles() {
+        try {
+            boolean indexEntryExists = Files.exists(storedRulesFile, LinkOption.NOFOLLOW_LINKS);
+            if (!indexEntryExists && !storeCreationAllowed) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+            }
+
+            if (!Files.exists(storeFolder, LinkOption.NOFOLLOW_LINKS)) {
+                if (!storeCreationAllowed) {
+                    throw new StoreInitializationFailedException("Cannot initialize violation store because its folder does not exist");
+                }
+                Files.createDirectories(storeFolder);
+            }
+            if (!Files.isDirectory(storeFolder)) {
+                throw new StoreInitializationFailedException(String.format("Violation store folder is not a directory: %s", storeFolder));
+            }
+
+            if (!indexEntryExists) {
+                if (integrityMode == IntegrityMode.FAIL) {
+                    // fail is deliberately read-only, including when the index is absent
+                    return;
+                }
+                Files.createFile(storedRulesFile);
+                indexEntryExists = true;
+            }
+            if (!Files.isRegularFile(storedRulesFile, LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "The index must be a regular file directly in the store folder: %s", storedRulesFile));
+            }
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (IOException | SecurityException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Properties loadStoredRulesIfPresent() {
+        Properties result = new Properties();
+        if (!Files.exists(storedRulesFile, LinkOption.NOFOLLOW_LINKS)) {
+            return result;
+        }
+        try (FileInputStream input = new FileInputStream(storedRulesFile.toFile())) {
+            result.load(input);
+            return result;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        requireInitialized();
+        synchronized (folderLock) {
+            return loadStoredRulesIfPresent().containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        requireInitialized();
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (folderLock) {
+            Properties storedRules = loadStoredRulesIfPresent();
+            String ruleDescription = rule.getDescription();
+            boolean known = storedRules.containsKey(ruleDescription);
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR && !known) {
+                return;
+            }
+
+            String ruleFileName;
+            if (known) {
+                ruleFileName = storedRules.getProperty(ruleDescription);
+            } else {
+                ruleFileName = createRuleFileName(ruleDescription);
+                validateNewSaveTarget(storedRules, ruleDescription, ruleFileName);
+            }
+            Path ruleFile = validateSavePath(storedRules, ruleDescription, ruleFileName);
+
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR && known) {
+                forgetRule(storedRules, ruleDescription, ruleFile);
+                return;
+            }
+
+            byte[] content = encodeViolations(violations);
+            boolean targetExisted = Files.exists(ruleFile, LinkOption.NOFOLLOW_LINKS);
+            try {
+                writeViolationFile(ruleFile, content, targetExisted);
+                if (!known) {
+                    storedRules.setProperty(ruleDescription, ruleFileName);
+                    try {
+                        writeStoredRules(storedRules);
+                    } catch (RuntimeException e) {
+                        deleteIfCreated(ruleFile, targetExisted);
+                        throw e;
+                    }
+                }
+            } catch (StoreUpdateFailedException e) {
+                throw e;
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+    }
+
+    private void validateNewSaveTarget(Properties storedRules, String description, String ruleFileName) {
+        for (String otherDescription : storedRules.stringPropertyNames()) {
+            if (!otherDescription.equals(description) && ruleFileName.equals(storedRules.getProperty(otherDescription))) {
+                throw rejectedSave("the file name is already recorded by another rule");
+            }
+        }
+        Path candidate = validateSavePath(storedRules, description, ruleFileName);
+        if (Files.exists(candidate, LinkOption.NOFOLLOW_LINKS)) {
+            throw rejectedSave("the file name already names an existing file");
+        }
+    }
+
+    private Path validateSavePath(Properties storedRules, String description, String ruleFileName) {
+        if (ruleFileName == null || ruleFileName.isEmpty()) {
+            throw rejectedSave("the file name strategy returned no name");
+        }
+        Path candidate;
+        try {
+            candidate = storeFolder.resolve(ruleFileName).normalize();
+        } catch (InvalidPathException e) {
+            throw rejectedSave("the file name is not a valid path");
+        }
+        if (!isDirectChild(candidate) || candidate.equals(storedRulesFile.normalize())) {
+            throw rejectedSave("the file name does not resolve directly into the store folder");
+        }
+        if (Files.exists(candidate, LinkOption.NOFOLLOW_LINKS)) {
+            if (isIndexFile(candidate)) {
+                throw rejectedSave("the file name leads to stored.rules");
+            }
+            if (!Files.isRegularFile(candidate)) {
+                throw rejectedSave("the file name does not lead to a regular file");
+            }
+            if (!isDirectFile(candidate)) {
+                throw rejectedSave("the file name leads outside the store folder");
+            }
+        }
+        return candidate;
+    }
+
+    private StoreUpdateFailedException rejectedSave(String reason) {
+        return new StoreUpdateFailedException("Cannot update violation store: " + reason);
+    }
+
+    private void writeViolationFile(Path ruleFile, byte[] content, boolean targetExisted) throws IOException {
+        if (targetExisted) {
+            // An in-place write preserves symbolic and hard links. All store readers use
+            // the same folder lock, so no store can observe this write half finished.
+            Files.write(ruleFile, content);
+        } else {
+            Files.write(ruleFile, content);
+        }
+    }
+
+    private void deleteIfCreated(Path ruleFile, boolean existedBefore) {
+        if (!existedBefore) {
+            try {
+                Files.deleteIfExists(ruleFile);
+            } catch (IOException ignored) {
+                log.debug("Could not remove a newly created violation file after an index update failed", ignored);
+            }
+        }
+    }
+
+    private void forgetRule(Properties storedRules, String description, Path ruleFile) {
+        EntryAssessment entry = assessSingleEntry(description, storedRules.getProperty(description));
+        boolean sharedByAnotherEntry = false;
+        for (String otherDescription : storedRules.stringPropertyNames()) {
+            if (!otherDescription.equals(description)) {
+                EntryAssessment other = assessSingleEntry(otherDescription, storedRules.getProperty(otherDescription));
+                if (sameFile(entry, other)) {
+                    sharedByAnotherEntry = true;
+                    break;
+                }
+            }
+        }
+
+        try {
+            if (!sharedByAnotherEntry) {
+                deleteNamedFileAndTarget(entry);
+            }
+            storedRules.remove(description);
+            writeStoredRules(storedRules);
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        requireInitialized();
+        synchronized (folderLock) {
+            String ruleDetailsFileName = loadStoredRulesIfPresent().getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(ruleDetailsFileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String fileName) {
+        try {
+            String violationsText = new String(toByteArray(resolveExistingFile(fileName)), UTF_8);
+            List<String> result = new ArrayList<>();
+            Matcher matcher = UNESCAPED_LINE_BREAK.matcher(violationsText);
+            int start = 0;
+            while (matcher.find()) {
+                String line = violationsText.substring(start, matcher.start());
+                if (!line.isEmpty()) {
+                    result.add(unescape(line));
+                }
+                start = matcher.end();
+            }
+            String lastLine = violationsText.substring(start);
+            if (!lastLine.isEmpty()) {
+                result.add(unescape(lastLine));
+            }
+            return result;
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private Path resolveExistingFile(String fileName) throws IOException {
+        try {
+            Path path = storeFolder.resolve(fileName);
+            if (!isDirectChild(path.normalize()) || !Files.isRegularFile(path)) {
+                throw new IOException("Not a regular file directly in the store folder: " + fileName);
+            }
+            return path;
+        } catch (InvalidPathException e) {
+            throw new IOException("Invalid stored file name", e);
+        }
+    }
+
+    private String createRuleFileName(String ruleDescription) {
+        String result = ruleViolationFileNameStrategy.createRuleFileName(ruleDescription);
+        if (result == null || result.isEmpty()) {
+            throw rejectedSave("the file name strategy returned no name");
+        }
+        return result;
+    }
+
+    private byte[] encodeViolations(List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append('\n');
+        }
+        return builder.toString().getBytes(UTF_8);
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private void initializeFilesForRepairIfNecessary() {
+        // Kept as a named operation to make it explicit that repair may create the
+        // initially absent index, while fail remains strictly read-only.
+    }
+
+    private IntegrityResult inspectIntegrity(Properties storedRules) {
+        List<EntryAssessment> entries = new ArrayList<>();
+        for (String description : storedRules.stringPropertyNames()) {
+            entries.add(assessSingleEntry(description, storedRules.getProperty(description)));
+        }
+
+        markShared(entries);
+        markDerivedConditions(entries, storedRules);
+        List<String> unownedFiles = findUnownedFiles(entries);
+        return new IntegrityResult(entries, unownedFiles);
+    }
+
+    private EntryAssessment assessSingleEntry(String description, String fileName) {
+        EntryAssessment result = new EntryAssessment(description, fileName);
+        try {
+            result.path = storeFolder.resolve(fileName).normalize();
+            if (!isDirectChild(result.path)) {
+                result.broken = true;
+                return result;
+            }
+            if (Files.exists(result.path, LinkOption.NOFOLLOW_LINKS)) {
+                if (Files.isRegularFile(result.path)) {
+                    try {
+                        result.actualFile = result.path.toRealPath();
+                    } catch (IOException e) {
+                        result.broken = true;
+                        return result;
+                    }
+                    result.directFile = isDirectFile(result.path);
+                    result.broken = !result.directFile;
+                    result.resolved = result.directFile && containsNoViolations(result.path);
+                } else {
+                    result.broken = true;
+                }
+            } else {
+                result.broken = true;
+            }
+        } catch (InvalidPathException | SecurityException e) {
+            result.broken = true;
+        }
+        return result;
+    }
+
+    private boolean containsNoViolations(Path file) {
+        try {
+            String text = new String(toByteArray(file), UTF_8);
+            if (text.isEmpty()) {
+                return true;
+            }
+            for (int i = 0; i < text.length(); i++) {
+                char character = text.charAt(i);
+                if (character != '\n' && character != '\r') {
+                    return false;
+                }
+            }
+            return true;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void markShared(List<EntryAssessment> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                EntryAssessment first = entries.get(i);
+                EntryAssessment second = entries.get(j);
+                if (first.fileName.equals(second.fileName) || sameFile(first, second)) {
+                    first.shared = true;
+                    second.shared = true;
+                }
+            }
+        }
+    }
+
+    private boolean sameFile(EntryAssessment first, EntryAssessment second) {
+        if (first.actualFile != null && second.actualFile != null) {
+            try {
+                return Files.isSameFile(first.actualFile, second.actualFile);
+            } catch (IOException ignored) {
+                return false;
+            }
+        }
+        if (first.path != null && second.path != null && Files.exists(first.path) && Files.exists(second.path)) {
+            try {
+                return Files.isSameFile(first.path, second.path);
+            } catch (IOException ignored) {
+                return false;
+            }
+        }
+        return false;
+    }
+
+    private void markDerivedConditions(List<EntryAssessment> entries, Properties storedRules) {
+        if (builtInRandomNames) {
+            return;
+        }
+        Map<String, List<EntryAssessment>> byDerivedName = new HashMap<>();
+        for (EntryAssessment entry : entries) {
+            entry.derivedFileName = createRuleFileNameForIntegrity(entry.description);
+            byDerivedName.computeIfAbsent(entry.derivedFileName, ignored -> new ArrayList<>()).add(entry);
+            entry.misplaced = !entry.fileName.equals(entry.derivedFileName);
+            if (entry.misplaced) {
+                entry.occupied = derivedNameIsOccupied(entry, entries, storedRules);
+            }
+        }
+        for (List<EntryAssessment> colliding : byDerivedName.values()) {
+            if (colliding.size() > 1) {
+                for (EntryAssessment entry : colliding) {
+                    entry.colliding = true;
+                }
+            }
+        }
+    }
+
+    private String createRuleFileNameForIntegrity(String description) {
+        String result;
+        try {
+            result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not derive a file name for rule '%s'", description), e);
+        }
+        if (result == null || result.isEmpty()) {
+            throw new StoreInitializationFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no name for rule '%s'", description));
+        }
+        return result;
+    }
+
+    private boolean derivedNameIsOccupied(EntryAssessment entry, List<EntryAssessment> entries, Properties storedRules) {
+        Path derivedPath;
+        try {
+            derivedPath = storeFolder.resolve(entry.derivedFileName).normalize();
+        } catch (InvalidPathException e) {
+            return true;
+        }
+        if (!isDirectChild(derivedPath)) {
+            return true;
+        }
+        for (EntryAssessment other : entries) {
+            if (other != entry && entry.derivedFileName.equals(other.fileName)) {
+                return true;
+            }
+        }
+        return Files.exists(derivedPath, LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private List<String> findUnownedFiles(List<EntryAssessment> entries) {
+        List<String> result = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolder)) {
+            for (Path file : files) {
+                if (!Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS) || isIndexFile(file)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (EntryAssessment entry : entries) {
+                    if (entry.actualFile != null) {
+                        try {
+                            if (Files.isSameFile(file, entry.actualFile)) {
+                                owned = true;
+                                break;
+                            }
+                        } catch (IOException ignored) {
+                            // A file which cannot be compared is reported as unowned.
+                        }
+                    }
+                }
+                if (!owned) {
+                    result.add(file.getFileName().toString());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        Collections.sort(result);
+        return result;
+    }
+
+    private void repair(Properties storedRules, IntegrityResult integrity) {
+        boolean indexChanged = false;
+        for (EntryAssessment entry : integrity.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                storedRules.remove(entry.description);
+                indexChanged = true;
+            } else if (entry.resolved) {
+                try {
+                    deleteNamedFileAndTarget(entry);
+                } catch (IOException e) {
+                    throw new StoreInitializationFailedException(e);
+                }
+                storedRules.remove(entry.description);
+                indexChanged = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                try {
+                    moveNamedFileTarget(entry, entry.derivedFileName);
+                } catch (IOException e) {
